function recurrenceDates(weekdays,start,end){if(!weekdays.length||!/^\d{4}-\d{2}-\d{2}$/.test(start||'')||!/^\d{4}-\d{2}-\d{2}$/.test(end||''))return [];const out=[];let cur=new Date(start+'T12:00:00Z');const lim=new Date(end+'T12:00:00Z');if(lim<cur||(lim-cur)/86400000>400)return [];while(cur<=lim){if(weekdays.includes(cur.getUTCDay()))out.push(cur.toISOString().slice(0,10));cur=new Date(cur.getTime()+86400000);}return out;}
const navigation=[['ROTINA','dashboard','Visão do dia',LayoutDashboard,'operation'],['','appointments','Agenda',CalendarDays,'operation'],['','daycare','Creche',Sun,'operation'],['','boarding','Hospedagem',Moon,'operation'],['','grooming','Banho e tosa',Scissors,'operation'],['CADASTROS','pets','Pets',Dog,'registry'],['','tutors','Tutores',Users,'registry'],['','packages','Pacotes',Ticket,'operation'],['','health','Saúde preventiva',HeartPulse,'health'],['','activities','Diário de atividades',Activity,'operation'],['GESTÃO','products','Produtos e estoque',Package,'inventory'],['','orders','Compras e vendas',ShoppingBag,'inventory'],['','team','Equipe e comissões',Users,'team'],['','finance','Financeiro',Wallet,'finance'],['','reports','Relatórios',ChartColumn,'reports'],['','alerts','Alertas e tarefas',Bell,'operation'],['CONFIGURAÇÕES','theme','Design e White Label',Palette,'settings'],['','settings','Configurações',Settings,'settings'],['','technical','Infraestrutura',Server,'technical']];
const labels={...kindLabels,pet:'Pet',tutor:'Tutor',service:'Serviço',professional:'Profissional',name:'Nome',start_at:'Entrada prevista',end_at:'Saída prevista',created_at:'Registrado em',status:'Situação',quote_cents:'Valor cobrado',description:'Descrição',amount_cents:'Valor',paid_cents:'Pago / recebido',due_date:'Vencimento',balance:'Créditos restantes',credits:'Contratados',expires_at:'Validade',source_type:'Origem',kind:'Tipo',quantity:'Quantidade',stock:'Estoque',min_stock:'Estoque mínimo',sku:'SKU',price_cents:'Preço',cost_cents:'Custo',reason:'Justificativa',method:'Método',server:'Servidor',database:'Banco de dados',files:'Arquivos',publication:'Publicação',secrets:'Credenciais',multi_company:'Multiempresa',external_messages:'Comunicação externa'};
