 {page==='team'&&<><p className="notice">Cadastre nomes e e-mails reais das duas proprietárias, duas monitoras e da profissional de banho e tosa. Para acesso compartilhado, autorize também essas contas na hospedagem privada.</p><div className="section-tools"><span>{list('users').length} pessoas cadastradas</span><button className="button" onClick={()=>setModal({type:'user',title:'Cadastrar pessoa'})}><Plus size={16}/>Adicionar pessoa</button></div><section className="panel"><Table records={list('users')} columns={ [['name','Nome'],['username','Usuário'],['email','E-mail'],['role','Perfil'],['salary_cents','Remuneração fixa'],['commission','Comissão']]} render={(k,r)=>k==='role'?roles[r.role]:k==='username'?(r.username||'—')+(r.must_change_password?' · senha pendente':''):k==='salary_cents'?money(r[k]):k==='commission'?r.commission_kind==='none'?'Sem comissão':r.commission_kind==='percent'?r.commission_value/100+'%':money(r.commission_value):r[k]} actions={r=><button className="text-btn" onClick={()=>setModal({type:'user',record:r,title:'Pessoa e permissões'})}>Editar / permissões</button>}/><h3 className="padded">Comissões apuradas</h3>{list('commissions').map(c=><div className="history-row" key={c.id}><strong>{find('users',c.user_id)?.name}</strong><span>{money(c.amount_cents)}</span><small>{date(c.created_at)}</small><button className="text-btn" onClick={()=>go('finance')}>Ver pagamento</button></div>)}</section></>}
