function OrderForm({lists,kind,save}){
 const [items,setItems]=useState([{product_id:'',lot_id:'',quantity:1,unit_cents:0}]);const change=(i,k,v)=>setItems(items.map((item,index)=>index===i?{...item,[k]:v}:item));
 return <Form fields={kind==='sale'?{tutor_id:['Tutor','tutors'],pet_id:['Pet','pets'],discount_cents:['Desconto autorizado (R$)','money'],notes:['Observações','textarea']}:{supplier_id:['Fornecedor','suppliers',true],discount_cents:['Desconto (R$)','money'],notes:['Observações','textarea']}} initial={{discount_cents:0}} lists={lists} save={v=>save({...v,kind,items})} submit={'Confirmar '+kindLabels[kind].toLowerCase()}><h3>Itens</h3>{items.map((item,i)=><div className="order-item" key={i}><label><span>Produto *</span><select required value={item.product_id} onChange={e=>{const p=lists.products.find(p=>p.id===e.target.value);setItems(items.map((it,index)=>index===i?{...it,product_id:p.id,unit_cents:kind==='sale'?p.price_cents:p.cost_cents,lot_id:''}:it));}}><option value="">Selecione</option>{lists.products.filter(p=>p.active).map(p=><option key={p.id} value={p.id}>{p.name} · estoque {p.stock}</option>)}</select></label><label><span>Quantidade</span><input required min="1" step="1" type="number" value={item.quantity} onChange={e=>change(i,'quantity',Number(e.target.value))}/></label><label><span>{kind==='sale'?'Preço':'Custo'} (R$)</span><input required min="0" step=".01" type="number" disabled={kind==='sale'} value={item.unit_cents/100} onChange={e=>change(i,'unit_cents',Math.round(Number(e.target.value)*100))}/></label><label><span>Lote</span><select value={item.lot_id} onChange={e=>change(i,'lot_id',e.target.value)}><option value="">Sem lote</option>{lists.lots.filter(l=>l.product_id===item.product_id).map(l=><option key={l.id} value={l.id}>{l.name} · {date(l.expires_date)}</option>)}</select></label><button type="button" className="icon-btn" aria-label="Remover item" disabled={items.length===1} onClick={()=>setItems(items.filter((it,index)=>index!==i))}><X size={16}/></button></div>)}<button type="button" className="text-btn" onClick={()=>setItems([...items,{product_id:'',lot_id:'',quantity:1,unit_cents:0}])}><Plus size={15}/>Adicionar item</button><p className="notice">Preço dos produtos é conferido no servidor. A operação só terá sucesso se estoque e financeiro forem gravados juntos.</p></Form>;
}
function UserForm({record:r,lists,save}){
 const initial=r?{commission_period:'monthly',commission_condition:'completed',bonus_kind:'none',bonus_value:0,bonus_target:0,...r,permissions:JSON.parse(r.permissions),commission_services:JSON.parse(r.commission_services)}:{name:'',email:'',username:'',role:'operation',active:true,salary_cents:0,commission_kind:'none',commission_value:0,commission_basis:'charged',commission_services:[],permissions:{},job_title:'',commission_period:'monthly',commission_condition:'completed',bonus_kind:'none',bonus_value:0,bonus_target:0};
 return <Form fields={{name:['Nome','text',true],username:['Usuário de acesso (login por nome, ex.: maria)','text',true],email:['E-mail de acesso','email',true],password:['Senha de acesso (mín. 8 caracteres)'+(r?' — em branco mantém a atual':''),'password',!r],role:['Perfil','select',true,'management|operation|technical'],active:['Acesso ativo','checkbox'],job_title:['Função no estabelecimento','text'],salary_cents:['Remuneração fixa por apuração (R$)','money'],commission_period:['Período de apuração','select',true,'daily|weekly|monthly'],commission_condition:['Apurar comissão quando','select',true,'completed|paid'],commission_pay_after_period:['Liberar pagamento somente após encerrar a apuração','checkbox'],bonus_kind:['Bonificação','select',true,'none|fixed|percent'],bonus_target:['Meta de atendimentos concluídos no período','number'],commission_kind:['Comissão','select',true,'none|fixed|percent'],commission_basis:['Base de cálculo','select',true,'charged|allocated']}} initial={initial} lists={lists} save={save}>{(v,setV)=><>{[['commission_kind','commission_value','Comissão'],['bonus_kind','bonus_value','Bonificação']].map(([kind,value,label])=>v[kind]!=='none'&&<label key={value}><span>{label} {v[kind]==='percent'?'(%)':'fixa (R$)'}</span><input type='number' min='0' max={v[kind]==='percent'?100:undefined} step='.01' required value={(v[value]||0)/100} onChange={e=>setV({...v,[value]:Math.round(Number(e.target.value)*100)})}/></label>)}<fieldset><legend>Serviços elegíveis para comissão</legend><div className="checks">{[...lists.services.filter(s=>s.kind!=='extra'),{id:'products',name:'Vendas de produtos'}].map(s=><label key={s.id}><input type="checkbox" checked={v.commission_services.includes(s.id)} onChange={e=>setV({...v,commission_services:e.target.checked?[...v.commission_services,s.id]:v.commission_services.filter(id=>id!==s.id)})}/>{s.name}</label>)}</div></fieldset><p className="notice">Escolha apuração na conclusão ou após recebimento. A regra é preservada em cada operação; pagamentos ficam no financeiro. A gestão define e redefine aqui a senha de acesso de cada pessoa.</p><details><summary>Permissões por área e ação</summary>{Object.entries(permissionNames).map(([domain,label])=><div className="permission-row" key={domain}><strong>{label}</strong>{['read','create','edit','cancel','delete','export','approve'].map(a=><label key={a}><small>{{read:'Ler',create:'Criar',edit:'Editar',cancel:'Cancelar',delete:'Excluir',export:'Exportar',approve:'Aprovar'}[a]}</small><select value={v.permissions[domain]?.[a]===undefined?'':String(v.permissions[domain][a])} onChange={e=>{const p=structuredClone(v.permissions);p[domain]||={};if(e.target.value==='')delete p[domain][a];else p[domain][a]=e.target.value==='true';setV({...v,permissions:p});}}><option value="">Perfil</option><option value="true">Sim</option><option value="false">Não</option></select></label>)}</div>)}</details></>}</Form>;
}
function UploadForm({modal,save}){
 const operationKey=useRef(crypto.randomUUID());
 const [documentType,setDocumentType]=useState('');
 const [file,setFile]=useState(null),[kind,setKind]=useState(modal.brand?'brand':modal.kind||'document'),[busy,setBusy]=useState(false),[error,setError]=useState('');
 return <form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{const f=new FormData();f.set('file',file);f.set('kind',kind);if(modal.pet_id)f.set('pet_id',modal.pet_id);if(modal.health_id)f.set('health_id',modal.health_id);if(modal.appointment_id)f.set('appointment_id',modal.appointment_id);if(modal.activity_id)f.set('activity_id',modal.activity_id);if(kind==='document')f.set('document_type',documentType);await save(f,operationKey.current);}catch(e){setError(e.message);}finally{setBusy(false);}}}>{modal.pet_id&&<div className='pet-confirmation'><p>Arquivo vinculado ao cadastro deste animal</p><PetIdentity petId={modal.pet_id} large/></div>}{!modal.brand&&<label><span>Tipo</span><select value={kind} onChange={e=>{operationKey.current=crypto.randomUUID();setKind(e.target.value);}}><option value="document">Documento ou comprovante</option><option value="activity">Foto de atividade</option>{modal.appointment_id&&<><option value="before">Foto antes do atendimento</option><option value="after">Foto depois do atendimento</option></>}</select></label>}{kind==='document'&&<label><span>Tipo / finalidade do documento</span><input value={documentType} placeholder='Ex.: termo de autorização ou carteira de vacinação' onChange={e=>{operationKey.current=crypto.randomUUID();setDocumentType(e.target.value);}}/></label>}<label className="upload-area"><Upload size={29}/><strong>Escolha um arquivo</strong><small>JPEG, PNG, WebP{kind==='document'?' ou PDF':''} · até 5 MB</small><input type="file" required accept={modal.brand?'image/jpeg,image/png':kind==='document'?'image/jpeg,image/png,image/webp,application/pdf':'image/jpeg,image/png,image/webp'} onChange={e=>{operationKey.current=crypto.randomUUID();setFile(e.target.files[0]);}}/></label>{error&&<p className="error">{error}</p>}<div className="form-footer"><small>Arquivo privado da empresa.</small><button disabled={!file||busy} className="button">{busy?'Enviando…':'Salvar arquivo'}</button></div></form>;
}

